{
  "root": "main_stack",
  "state": {
    "schedule": [
      {
        "dayDate": "Day 1",
        "title": "Historic Higashiyama & Gion",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/3a/Kiyomizu-dera_Kyoto_Japan.jpg/1200px-Kiyomizu-dera_Kyoto_Japan.jpg",
        "morningActivity": "Kiyomizu-dera Temple. Explore the iconic wooden stage and hillside views. Travel: Bus 206 from Kyoto Station.",
        "afternoonActivity": "Sannenzaka & Tea Ceremony. Traditional walk followed by an authentic tea experience in a Gion machiya.",
        "eveningActivity": "Gion District. Evening walk through Hanami-koji for traditional architecture and geiko sightings."
      },
      {
        "dayDate": "Day 2",
        "title": "Arashiyama Nature & Zen",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/b5/Arashiyama_Bamboo_Grove_Kyoto.jpg/1200px-Arashiyama_Bamboo_Grove_Kyoto.jpg",
        "morningActivity": "Arashiyama Bamboo Grove & Tenryu-ji. Walk the bamboo paths and world-class Zen garden. Travel: JR Sagano Line.",
        "afternoonActivity": "Adashino Nenbutsu-ji. A quieter, atmospheric temple further up the hill. Travel: Walking or local bus.",
        "eveningActivity": "Togetsukyo Bridge. Sunset views over the Katsura River."
      },
      {
        "dayDate": "Day 3",
        "title": "Market Flavors & Shrines",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/22/Nishiki_Market_Kyoto_Japan.jpg/1200px-Nishiki_Market_Kyoto_Japan.jpg",
        "morningActivity": "Fushimi Inari Shrine. Hike through the thousands of vermilion torii gates. Travel: JR Nara Line.",
        "afternoonActivity": "Nishiki Market. Explore 'Kyoto's Kitchen' for street food like octopus balls and pickled vegetables.",
        "eveningActivity": "Pontocho Alley. Final riverside dinner at a narrow, traditional alleyway."
      }
    ],
    "budget_summary": [
      {
        "Category": "Food",
        "Estimated Cost (USD)": "$360",
        "Notes": "$60/person/day avg"
      },
      {
        "Category": "Activities",
        "Estimated Cost (USD)": "$150",
        "Notes": "Entry fees + Tea Ceremony"
      },
      {
        "Category": "Transport",
        "Estimated Cost (USD)": "$60",
        "Notes": "Subway/Bus passes"
      },
      {
        "Category": "Total",
        "Estimated Cost (USD)": "$570",
        "Notes": "Within $600 budget"
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "lg",
        "padding": 16
      },
      "children": [
        "title",
        "intro_text",
        "neighborhood_heading",
        "neighborhood_card",
        "schedule_heading",
        "schedule_table",
        "budget_heading",
        "budget_table",
        "actions_heading",
        "actions_stack",
        "sources_heading",
        "sources_stack"
      ]
    },
    "title": {
      "type": "Text",
      "props": {
        "text": "Kyoto Cultural & Culinary Itinerary",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "This 3-day plan is optimized for two adults, focusing on the historical Higashiyama and Arashiyama districts while staying near Kyoto Station for maximum transit efficiency."
      },
      "children": []
    },
    "neighborhood_heading": {
      "type": "Text",
      "props": {
        "text": "Recommended Neighborhood: Shimogyo-ku (Near Kyoto Station)",
        "variant": "h2"
      },
      "children": []
    },
    "neighborhood_card": {
      "type": "Card",
      "props": {},
      "children": [
        "neighborhood_card_stack"
      ]
    },
    "neighborhood_card_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "neighborhood_image",
        "neighborhood_text_stack"
      ]
    },
    "neighborhood_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/13/Kyoto_Station_building_2015.jpg/1200px-Kyoto_Station_building_2015.jpg",
        "fit": "cover"
      },
      "children": []
    },
    "neighborhood_text_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "neighborhood_icon",
        "neighborhood_text"
      ]
    },
    "neighborhood_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/building.svg"
      },
      "children": []
    },
    "neighborhood_text": {
      "type": "Text",
      "props": {
        "text": "Staying near Kyoto Station provides immediate access to all JR lines, the Karasuma Subway, and the city's central bus hub. This location minimizes transit time to all major districts and offers abundant evening dining options."
      },
      "children": []
    },
    "schedule_heading": {
      "type": "Text",
      "props": {
        "text": "3-Day Daily Schedule",
        "variant": "h2"
      },
      "children": []
    },
    "schedule_table": {
      "type": "Table",
      "props": {
        "statePath": "/schedule",
        "columns": [
          {
            "key": "dayDate",
            "label": "Day"
          },
          {
            "key": "title",
            "label": "Theme"
          },
          {
            "key": "morningActivity",
            "label": "Morning"
          },
          {
            "key": "afternoonActivity",
            "label": "Afternoon"
          },
          {
            "key": "eveningActivity",
            "label": "Evening"
          },
          {
            "key": "image",
            "label": "Image"
          }
        ],
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "dayDate",
        "highlightColumns": [
          "title"
        ]
      },
      "children": []
    },
    "budget_heading": {
      "type": "Text",
      "props": {
        "text": "Budget & Transit Summary",
        "variant": "h2"
      },
      "children": []
    },
    "budget_table": {
      "type": "Table",
      "props": {
        "statePath": "/budget_summary",
        "columns": [
          {
            "key": "Category",
            "label": "Category"
          },
          {
            "key": "Estimated Cost (USD)",
            "label": "Estimated Cost (USD)"
          },
          {
            "key": "Notes",
            "label": "Notes"
          }
        ],
        "domain": "comparison",
        "preferredPresentation": "table",
        "numericColumns": [
          "Estimated Cost (USD)"
        ]
      },
      "children": []
    },
    "actions_heading": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "book_tea_button",
        "bus_map_button"
      ]
    },
    "book_tea_button": {
      "type": "Button",
      "props": {
        "label": "Book Tea Ceremony"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.kyoto-maikoya.com/"
          }
        }
      },
      "children": []
    },
    "bus_map_button": {
      "type": "Button",
      "props": {
        "label": "Kyoto Bus Map"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.city.kyoto.lg.jp/kotsu/page/0000019770.html"
          }
        }
      },
      "children": []
    },
    "sources_heading": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "kyoto_guide_button",
        "japan_guide_button"
      ]
    },
    "kyoto_guide_button": {
      "type": "Button",
      "props": {
        "label": "Kyoto City Official Guide",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://kyoto.travel/en/"
          }
        }
      },
      "children": []
    },
    "japan_guide_button": {
      "type": "Button",
      "props": {
        "label": "Japan-Guide Kyoto",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.japan-guide.com/e/e2158.html"
          }
        }
      },
      "children": []
    }
  }
}
